-- Mountain Prime Phase 2 data port — generated 2026-07-29T03:52:49.289Z
-- Additive + idempotent. Matches prod rows by name; never touches other tenants.
-- Apply: cp /data/tannins.db /data/tannins.db.bak.$(date +%s) && sqlite3 /data/tannins.db < data/mountain-prime/port-mp-phase2.sql
BEGIN;

-- ===== Flavor profiles (fill-only, matched by beverage name+type) =====
CREATE TEMP TABLE _pf (name TEXT, type TEXT, flavor TEXT);

Bursts with bright, candy-sweet orange leading the way, layered with juicy artificial grape and ripe strawberry notes that lean playful and tropical. The body is light and effervescent, with brisk carbonation that keeps the sweetness lively rather than cloying. The finish is short and sugary with a faint citrus tingle.'),
  ('Fountain Sodas (Coke, Diet Coke, Root Beer, Sprite, Ginger Ale, Iced Tea, Lemonade)','N/A','**Fountain Sodas**

**Coke:** Bold caramel and vanilla sweetness with hints of cola spice, bright carbonation, and a clean, slightly citrusy finish.

**Diet Coke:** Lighter, crisper than Coke with a clean cola flavor, subtle citrus lift, and a dry, effervescent finish with a touch of artificial sweetness.

**Root Beer:** Rich, creamy vanilla and wintergreen with hints of anise and sassafras, a smooth sweetness, and a frothy, lingering finish.

**Sprite:** Fresh lemon-lime brightness with clean, sharp sweetness, lively carbonation, and a crisp, refreshing finish.

**Ginger Ale:** Delicate ginger warmth with light sweetness, subtle citrus undertones, and a gentle, palate-cleansing effervescence.

**Iced Tea:** Brisk black tea flavor with mild tannin structure, a slightly earthy depth, and a clean, refreshing finish — lightly sweetened unless specified.

**Lemonade:** Bright, tangy lemon citrus balanced with straightforward sweetness, a juicy, fresh character, and a clean, tart finish.'),
  ('Graham''s Tawny Porto 10 Year','Port','Rich notes of dried fig, raisin, roasted hazelnut, and orange peel give way to hints of caramel, vanilla, and a touch of espresso. Medium-full bodied with a velvety, smooth texture, gentle acidity, and a naturally sweet, nutty character from extended oxidative aging. The finish is long and warming, with lingering dried fruit and toasted walnut.'),
  ('Hardy''s Tawny Porto 10 Year','Port','Rich dried fruit notes of raisin, fig, and apricot mingle with toasted walnut, caramel, and a hint of orange peel. The palate is smooth and medium-bodied with a gentle sweetness balanced by a subtle nuttiness from extended barrel aging. The finish is warm, lingering, and laced with vanilla and spice.'),
  ('Heck''s Czech Dark Lager','Beer','Rich notes of dark chocolate, roasted bread, and dried plum lead the palate, with subtle hints of toffee and a mild earthiness underneath. The body is medium-full with a smooth, creamy mouthfeel and low hop bitterness, keeping it approachable rather than heavy. The finish is clean and slightly sweet, with lingering caramel and a gentle roasted quality.'),
  ('Juices (Tomato, Clamato, Grapefruit, Pineapple)','N/A','**Tomato Juice:** Savory and earthy with bright acidity, notes of ripe tomato, subtle vegetal depth, and a clean, slightly tangy finish. Medium-bodied with a smooth, rounded texture.

**Clamato:** A savory, briny blend of tomato and clam broth with umami depth, mild spice, and a sharp, tangy finish. Light-bodied with a distinctive oceanic saltiness.

**Grapefruit Juice:** Vibrant and tart with bold citrus brightness, notes of bitter pith, and a refreshing, zesty finish. Light-bodied with a lively acidity and subtle underlying sweetness.

**Pineapple Juice:** Bright and tropical with intense sweet-tart notes of fresh pineapple, hints of floral and citrus undertones, and a juicy, lingering finish. Light to medium-bodied with a clean, refreshing acidity.'),
  ('Kettlehouse Cold Smoke 16oz Can','Beer','Smooth and approachable, Cold Smoke leads with roasted malt, dark chocolate, and a subtle hint of coffee, balanced by a touch of caramel sweetness. The body is medium-full with a creamy, almost silky texture that keeps it from feeling heavy. The finish is clean and slightly smoky, with very low bitterness.'),
  ('Lemon Ginger Mojito','Cocktail','Bright and zesty with fresh lemon citrus upfront, backed by a warm, spicy ginger kick and cool mint. Light-bodied with a lively, effervescent quality from the soda, balanced by a touch of sweetness from simple syrup and the clean bite of white rum. The finish is crisp and refreshing with a lingering ginger warmth.'),
  ('Mango Caliente','Cocktail','Bright, sun-ripened mango leads with a juicy tropical sweetness, followed by a slow-building heat from chili or jalapeño that lingers on the palate. A citrus element — typically lime — cuts through with sharp acidity, keeping the sweetness in check and adding a refreshing lift. The finish is warm and spicy, with a satisfying contrast between the fruit''s softness and the pepper''s persistent kick.'),
  ('Michelob Ultra 12oz Bottle','Beer','Crisp and light-bodied with subtle grain and faint hop bitterness, offering delicate notes of pale malt and a hint of citrus. Highly carbonated with a clean, refreshing finish that is dry and remarkably low in residual sweetness.'),
  ('Mint Citrus Fizz','Mocktail','Bright and refreshing, with a zesty burst of lemon and lime up front, layered with cool, clean spearmint. Light-bodied with lively carbonation that lifts the citrus and keeps the palate crisp. The finish is clean and tingly, fading with a gentle sweetness balanced by a subtle herbal coolness.'),
  ('N/V Almacita Pinot Noir Brut Rose','Rosé','Delicate notes of fresh strawberry, raspberry, and rose petal lead into hints of brioche and cream, reflecting its traditional méthode sparkling production. The palate is light-bodied with bright, lively acidity and fine, persistent bubbles. The finish is clean and refreshing with a subtle minerality and a touch of red fruit lingering at the close.'),
  ('N/V Bottex Bugey Cerdon Rose','Rosé','Bursting with fresh red berry aromas of wild strawberry, raspberry, and cherry, with a subtle floral violet note and a hint of candied sweetness. Light-bodied and lively with refreshing acidity, it''s gently frothy with a low alcohol, off-dry character. The finish is clean, bright, and delicately fruity.'),
  ('N/V Champalou Vouvray Brut','Sparkling Wine','Crisp green apple, quince, and white flower aromas lead into a palate of lemon curd, honeysuckle, and a hint of brioche from light lees aging. The mousse is delicate and persistent, with bright, mouthwatering acidity and just a whisper of Chenin Blanc''s characteristic honeyed richness keeping it from being bone dry. The finish is clean, mineral, and refreshingly long with a chalky, stony quality.'),
  ('N/V Chartogne Taillet ''Cuvve Ste Anne''','Sparkling Wine','Bright and expressive with notes of green apple, lemon zest, white peach, and a hint of brioche from light lees aging. The mousse is fine and creamy, with lively acidity that keeps it fresh and energetic. The finish is clean and mineral-driven with a subtle chalky texture characteristic of the Champagne terroir.'),
  ('N/V Fourny et Fils Brut Rose 1er Cru','Rosé','Delicate strawberry, fresh raspberry, and rose petal aromas lead into a palate of red cherry, brioche, and a hint of citrus zest. The mousse is fine and persistent, with bright, lively acidity and an elegant, dry structure. The finish is clean and mineral-driven with a lingering floral quality.'),
  ('N/V J. Lassalle Brut 1er Cru ''Preference''','Sparkling Wine','Bright and elegant, with notes of green apple, lemon zest, brioche, and white flowers, underscored by a chalky minerality characteristic of Premier Cru Montagne de Reims fruit. The mousse is fine and persistent, with lively acidity that keeps the palate fresh and energized. The finish is clean and moderately long, with a toasty, slightly honeyed quality that adds depth.'),
  ('N/V Marchesine Fraciacorta ''Nitens'' Brut DOCG','Sparkling Wine','Bright and elegant with notes of white peach, citrus zest, and toasted brioche, underpinned by a hint of almond and fresh flowers. The palate is medium-bodied with lively, fine-bubbled acidity and a creamy mousse. The finish is crisp and persistent, with a clean mineral lift.'),
  ('N/V Paolo Fallabrino ''Alcyone'' Tannat 500ml','Dessert','Rich and concentrated with dark fruit — blackberry preserves, dried plum, and black cherry — layered with notes of bittersweet chocolate, espresso, and a hint of dried violet. The body is full and lush, with Tannat''s characteristic firm tannins softened by the wine''s residual sweetness, creating a velvety texture. The finish is long and warming, with lingering cocoa and a touch of dried fig.'),
  ('N/V Pierre Sparr Cremant D''Alsace','Sparkling Wine','Bright and refreshing with notes of green apple, white pear, and lemon zest, layered with subtle floral hints and a touch of brioche from its traditional method production. The palate is light to medium-bodied with lively, fine bubbles and crisp acidity that keeps it vibrant and clean. The finish is dry, elegant, and pleasantly lingering with a hint of minerality.'),
  ('N/V Sommariva Prosecco Superior','Sparkling Wine','Bright and lively with notes of green apple, white peach, and delicate floral hints of acacia and wisteria. Light-bodied with crisp acidity, fine persistent bubbles, and a touch of almond on the clean, refreshing finish. Lightly off-dry with just enough residual sweetness to balance the zesty citrus undertones.'),
  ('N/V Soter Estate Brut Reserve','Sparkling Wine','Crisp green apple, lemon curd, and toasted brioche lead the palate, with subtle notes of white peach and fresh cream lending elegance and depth. The mousse is fine and persistent, backed by bright, focused acidity and a touch of minerality that keeps the wine lively. The finish is clean and lingering, with a faint chalky texture and hints of almond.'),
  ('N/V Treveri Cellars Blanc de Blanc 375ml','Sparkling Wine','Crisp and elegant, with bright notes of green apple, lemon zest, and white peach underpinned by a subtle yeasty brioche quality. Light-bodied with lively, fine bubbles and refreshing acidity that keeps it clean and vibrant. The finish is dry, citrus-driven, and pleasantly long.'),
  ('N/V Tutela Organic Prosecco 200ml','Sparkling Wine','Bright and refreshing with lively bubbles, delivering crisp green apple, white peach, and delicate floral notes of wisteria and acacia. Light-bodied with clean, zippy acidity and a touch of natural sweetness. The finish is clean and short with a pleasant almond biscuit quality.'),
  ('New Haikkado Rice Lager 16oz Can','Beer','Crisp and clean with subtle notes of steamed white rice, mild grain, and a faint floral hop aroma. Light-bodied with soft carbonation, very low bitterness, and a gentle sweetness that keeps it refreshing. The finish is short and dry, making it easy-drinking and smooth throughout.'),
  ('Original Hard Cider','Cider','Crisp and refreshing with bright green apple and a hint of tart citrus, balanced by a light natural sweetness. Medium-bodied with lively carbonation and clean acidity that keeps it from feeling heavy. The finish is dry and clean, with a lingering orchard fruit note.'),
  ('PBR 16oz Can','Beer','Light, crisp, and mildly grainy with subtle notes of corn, pale malt, and faint floral hops. Very low bitterness and high carbonation give it a clean, refreshing character with minimal complexity. The finish is short and dry, making it an easy-drinking, approachable lager.'),
  ('Pig''s Ass Porter','Beer','Rich and roasty with dark chocolate, espresso, and a subtle smokiness up front, layered over notes of caramel and dried dark fruit. Full-bodied and smooth with low bitterness, it finishes with a lingering cocoa warmth that keeps it approachable rather than heavy.'),
  ('Prickly Pear Pale Ale','Beer','Bright and refreshing with sweet-tart prickly pear fruit up front, layered over the citrusy, floral hop character typical of a pale ale. The body is light to medium with a crisp, clean bitterness that keeps the fruit from feeling cloying. Finishes dry with a lingering berry-like sweetness and a subtle earthy hop note.'),
  ('Radio Silence','Cocktail','Bright and floral with a silky texture, this cocktail leads with fresh elderflower and delicate violet blossoms, underscored by the crisp, citrusy snap of lemon and the clean agave backbone of blanco tequila. The egg white lends a soft, frothy mouthfeel that smooths the acidity into a gentle, creamy lift. The finish is light and perfumed, fading with a whisper of citrus zest and sweet floral nectar.'),
  ('Red Bull & Sugar Free Red Bull','N/A','**Red Bull** delivers a sharp, effervescent burst of sweet citrus and tart green apple with a distinct medicinal, slightly herbal edge from the taurine and B-vitamins. The body is light and highly carbonated, with a sugary finish that lingers alongside a faint bitterness.

**Sugar Free Red Bull** mirrors the same citrusy, herbal profile but with a thinner body and a subtle artificial sweetness that fades quickly, leaving a slightly drier, more pronounced bitter finish.'),
  ('San Pellegrino 500ml','N/A','Crisp and clean with a fine, persistent effervescence that delivers a subtle minerality and a faint hint of salinity. The bubbles are delicate rather than aggressive, leaving a refreshing, neutral finish with just a whisper of alkaline earthiness.'),
  ('San Pellegrino 750ml','N/A','Crisp and clean with a fine, persistent effervescence and a subtle mineral salinity on the palate. The carbonation is gentle rather than aggressive, leaving a refreshing, slightly alkaline finish with no sweetness or fruit character.'),
  ('Shock Value','Cocktail','Bright and herbaceous with cool cucumber and fresh citrus upfront, layered with the honeyed floral notes of Lillet and a hint of orange from the Cointreau. The absinthe spray adds a subtle anise intrigue on the nose without overwhelming the palate. Crisp and light-bodied with lively acidity and a clean, slightly aromatic finish.'),
  ('Sierra Nevada Pale Ale 12oz Bottle','Beer','Bright and aromatic with piney, floral hops upfront and a clean citrus zest character. Medium-bodied with a firm but balanced bitterness and a biscuity, lightly caramel malt backbone. The finish is crisp and moderately dry with a lingering hop resin note.'),
  ('Snow Dust Rice Lager','Beer','Crisp and light-bodied with delicate notes of rice sweetness, subtle grain, and a clean, faintly floral aroma. Mild hop bitterness keeps it refreshing without assertiveness, with a soft, slightly creamy mouthfeel from the rice adjunct. The finish is short and clean, leaving a gentle, dry crispness.'),
  ('St. Agrestis Phony Negroni','N/A','Bold bitter orange and Campari-like herbal complexity lead, layered with sweet vermouth spice — cardamom, clove, and a whisper of vanilla — all without alcohol''s burn. The body is medium and slightly viscous, mimicking a well-stirred cocktail, with a clean, pleasantly lingering bitter finish.'),
  ('Steakhouse 74','Mocktail','Bright and boldly refreshing, with forward notes of smoky char, cracked black pepper, and savory umami balanced by a subtle sweetness from caramelized stone fruit. The body is medium and slightly syrupy, with a lively citrus acidity cutting through the richness. The finish is long, dry, and warming — evoking the essence of a perfectly seared cut without a drop of alcohol.'),
  ('Stella Artois 0% 12oz Bottle','Beer','Crisp and clean with mild grain and light floral hop notes, offering a faint sweetness reminiscent of pale malt. The body is light and refreshing with gentle carbonation and minimal bitterness. The finish is short and neutral, making it an easy, approachable drink.'),
  ('Stella Artois 12oz Bottle','Beer','Crisp and clean with mild notes of grainy malt, faint honey sweetness, and a subtle floral hop aroma. Light-bodied with a gentle bitterness that keeps it refreshing rather than sharp. The finish is dry and smooth with a slight bready aftertaste.'),
  ('The Iron Sage','Cocktail','Briny and herbaceous up front, with the sharp salinity of olive brine meeting the piney, resinous lift of rosemary and the earthy warmth of thyme. The peppercorn tincture adds a slow, building heat that cuts through the clean, neutral vodka base. The finish is long and savory, dry as bone, with a lingering herbal bitterness.'),
  ('The Violet Hour','Cocktail','Bright and floral with crème de violette at the forefront, layered over the botanical complexity of gin and a whisper of lemon citrus. The palate is silky and lightly sweet with a delicate herbal backbone, balanced by a clean, tart finish that keeps it refreshing rather than cloying.'),
  ('Velvet Honey','Mocktail','Lush and golden, with upfront notes of wildflower honey, ripe peach, and a whisper of vanilla. The body is silky and medium-weight, balanced by a bright citrus lift — likely lemon or yuzu — that keeps the sweetness from feeling heavy. The finish is smooth and lingering, with a subtle floral warmth.'),
  ('White Claw Black Cherry 12oz Can','Seltzer','Crisp and refreshing with a light, candy-like black cherry sweetness that''s bright without being cloying. The carbonation is lively and clean, with a subtle tartness that keeps it balanced. Finishes dry and light with a faint fruity linger.'),
  ('White Claw Mango 12oz Can','Seltzer','Bright and straightforward mango flavor leads with a tropical sweetness that''s light and refreshing rather than candy-like. The carbonation is crisp and clean, keeping the palate lively, while the alcohol remains virtually imperceptible. Finishes dry and quick with a subtle citrus lift.'),
  ('Wild River IPA Series','Beer','Bold citrus and tropical fruit notes — think grapefruit, mango, and pine resin — ride on a firm, resinous bitterness characteristic of a West Coast-style IPA. The body is medium with a clean, crisp malt backbone that keeps the hop intensity in balance. The finish is long, dry, and pleasantly bitter with a lingering citrus zest.');

SELECT '!! UNMATCHED FLAVOR BEVERAGE: ' || name || ' [' || type || ']'
  FROM _pf f WHERE NOT EXISTS (SELECT 1 FROM beverages b WHERE b.name=f.name AND b.type=f.type);

UPDATE beverages SET flavor_profile =
    (SELECT f.flavor FROM _pf f WHERE f.name=beverages.name AND f.type=beverages.type)
  WHERE (flavor_profile IS NULL OR flavor_profile='')
    AND EXISTS (SELECT 1 FROM _pf f WHERE f.name=beverages.name AND f.type=beverages.type);

-- ===== Menu pairings (matched by dish name + beverage name/type, tenant-scoped) =====
CREATE TEMP TABLE _pp (dish TEXT, bev TEXT, bevtype TEXT, ai TEXT, house TEXT, sort INT);

SELECT '!! UNMATCHED PAIRING DISH: ' || dish FROM _pp p WHERE NOT EXISTS
  (SELECT 1 FROM menu_items mi JOIN restaurants r ON r.id=mi.restaurant_id WHERE r.slug='mountain-prime' AND mi.name=p.dish);
SELECT '!! UNMATCHED PAIRING BEVERAGE: ' || bev FROM _pp p WHERE NOT EXISTS
  (SELECT 1 FROM wine_list wl JOIN beverages b ON b.id=wl.beverage_id JOIN restaurants r ON r.id=wl.restaurant_id WHERE r.slug='mountain-prime' AND b.name=p.bev AND b.type=p.bevtype);

INSERT OR IGNORE INTO menu_item_pairings (menu_item_id, wine_list_id, ai_pairing_text, house_pairing_text, sort_order)
  SELECT mi.id, wl.id, p.ai, p.house, p.sort
  FROM _pp p
  JOIN restaurants r ON r.slug='mountain-prime'
  JOIN menu_items mi ON mi.restaurant_id=r.id AND mi.name=p.dish
  JOIN wine_list wl ON wl.restaurant_id=r.id
  JOIN beverages b ON b.id=wl.beverage_id AND b.name=p.bev AND b.type=p.bevtype;

COMMIT;

-- Summary (should match the local counts printed by the generator):
SELECT 'flavor filled (global): ' || COUNT(*) FROM beverages WHERE flavor_profile IS NOT NULL AND flavor_profile!='';
SELECT 'MP pairings total: ' || COUNT(*) FROM menu_item_pairings mip JOIN wine_list wl ON wl.id=mip.wine_list_id JOIN restaurants r ON r.id=wl.restaurant_id WHERE r.slug='mountain-prime';
